from pathlib import Path

p = Path('ClockTimer.js')
s = p.read_text()

needle = '''        closeOpenRange() {\n'''
if s.count(needle) != 1:
    raise SystemExit(f'closeOpenRange anchor count: {s.count(needle)}')

method = '''        close() {\n            const openInsert =\n                this.#openEndedRange;\n\n            const openOverwrite =\n                this.#openOverwriteRange;\n\n            if (!openInsert && !openOverwrite) {\n                throw new Error(\n                    "close() requires an open-ended insert or overwrite."\n                );\n            }\n\n            const nowDate =\n                new Date();\n\n            const now =\n                this.#getCurrentTimelineTime(\n                    nowDate\n                );\n\n            if (openInsert) {\n                const start =\n                    this.#dateToTimelineTime(\n                        openInsert.startDate\n                    );\n\n                const previous =\n                    Number.isFinite(\n                        this.#openEndedLastTick\n                    )\n                        ? this.#openEndedLastTick\n                        : start;\n\n                if (now > previous) {\n                    const delta =\n                        now - previous;\n\n                    this.#extendCalculatedEndTime(\n                        delta,\n                        openInsert.type\n                    );\n\n                    this.#shiftRangesAfter(\n                        previous,\n                        delta,\n                        openInsert\n                    );\n                }\n\n                openInsert.openEnded =\n                    false;\n\n                openInsert.endDate =\n                    new Date(\n                        nowDate.getTime()\n                    );\n\n                openInsert.rangeLength =\n                    Math.max(\n                        0,\n                        now - start\n                    );\n\n                this.#openEndedRange =\n                    undefined;\n\n                this.#openEndedLastTick =\n                    undefined;\n\n                this.#renderAllInsertedRanges();\n            }\n\n            if (openOverwrite) {\n                const previous =\n                    Number.isFinite(\n                        this.#openOverwriteLastTick\n                    )\n                        ? this.#openOverwriteLastTick\n                        : openOverwrite.start;\n\n                if (now > previous) {\n                    const net =\n                        this.#getOverwriteCalculatedEndDelta(\n                            previous,\n                            now,\n                            openOverwrite.type\n                        );\n\n                    this.#adjustCalculatedEndTime(\n                        net\n                    );\n\n                    this.#applyOverwriteMask(\n                        previous,\n                        now\n                    );\n\n                    this.#renderOverwriteRecord({\n                        ...openOverwrite,\n                        start: previous,\n                        end: now,\n                        openEnded: false\n                    });\n                }\n\n                openOverwrite.openEnded =\n                    false;\n\n                openOverwrite.end =\n                    Math.max(\n                        openOverwrite.start,\n                        now\n                    );\n\n                this.#openOverwriteRange =\n                    undefined;\n\n                this.#openOverwriteLastTick =\n                    undefined;\n            }\n\n            this.#tickAlignmentMilliseconds =\n                nowDate.getMilliseconds();\n\n            this.#stopTickTimer();\n\n            if (this.#needsTick()) {\n                this.#scheduleNextTick();\n            }\n\n            this.#refreshRingLayout(\n                this.#started\n                    ? now\n                    : undefined,\n                { refreshTickMarks: true }\n            );\n\n            return this;\n        }\n\n'''

s = s.replace(needle, method + needle, 1)

if '        close() {' not in s:
    raise SystemExit('close method missing after patch')

p.write_text(s)
